class LamportClock:
    def __init__(self):
        self.ts = 0

    def local_event(self):
        self.ts += 1
        return self.ts

    def send(self):
        self.ts += 1
        return self.ts

    def receive(self, incoming_ts):
        self.ts = max(self.ts, incoming_ts) + 1
        return self.ts
